/// Compute the estimated remaining battery life in hours.\n///\n/// * `capacity` – current charge as a percentage (0‑100).\n/// * `drain_per_hour` – average consumption per hour as a percentage.\n/// * `survival` – if true, apply a 10 % safety margin (multiply result by 0.9).\n///\n/// Returns `f64::INFINITY` when `drain_per_hour` is zero (no consumption).\npub fn compute_estimate(capacity: f64, drain_per_hour: f64, survival: bool) -> f64 {\n    if drain_per_hour <= 0.0 {\n        return f64::INFINITY;\n    }\n    let mut hours = capacity / drain_per_hour;\n    if survival {\n        hours *= 0.9; // 10% safety buffer\n    }\n    hours\n}\n
